/**
 * The formula-import corpus through the app's whole pipeline (keys module -> buildPremerged): openpyxl / XlsxWriter files (formulas with
 * and without stored results) and the Excel-saved twins of the same workbooks (tests/fixtures/formulaimport, generated by
 * tests/oracle/import-values/gen_corpus.py + author.ps1; values verified in real Excel by the oracle next to it).
 * expected.json holds the counters of every file under four configurations (tests/oracle/import-values/make-expected.ts rewrites it):
 * a change of behaviour shows up as a diff of that file.
 */
import fs from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { tokenize } from '../../src/core/formula/excelRef';
import { readBook } from '../../src/core/xlsx';
import { CONFIGS } from '../oracle/import-values/make-expected';
import { loadManifest, runCorpusFile, sheetOf, summarize, type Counts, type CorpusEntry } from '../oracle/import-values/lib';
import { snapshot } from '../golden/snapshot';

const DIR = path.resolve(__dirname, '../fixtures/formulaimport');
const expected = JSON.parse(fs.readFileSync(path.join(DIR, 'expected.json'), 'utf8')) as Record<string, Counts>;
const manifest: CorpusEntry[] = loadManifest(DIR);

describe('corpus: counters per file and configuration', () => {
  for (const e of manifest) {
    for (const cfg of CONFIGS) {
      it(`${e.file} | ${cfg.name}`, async () => {
        const r = await runCorpusFile(DIR, e.file, cfg, e.base ?? 'base.xlsx');
        expect(r.counts).toEqual(expected[`${e.file}|${cfg.name}`]);
        // the report agrees with the trace
        const st = r.result.report.formulaStats ?? [];
        const kept = st.reduce((a, x) => a + x.kept, 0), toValues = st.reduce((a, x) => a + x.toValues, 0), empty = st.reduce((a, x) => a + x.empty, 0);
        expect([kept, toValues, empty]).toEqual([r.counts.kept, r.counts.value, r.counts.empty]);
        expect(r.result.report.formulasKept).toBe(kept);
        expect(r.result.report.formulasToValues).toBe(toValues + empty);
        for (const [why, n] of Object.entries(r.counts.reasons)) expect(st.reduce((a, x) => a + (x.reasons[why] ?? 0), 0)).toBe(n);
        // an empty cell is reported
        if (r.counts.empty) expect(r.result.report.items.some((i) => i.code === 'formulasNoCache')).toBe(true);
        else expect(r.result.report.items.some((i) => i.code === 'formulasNoCache')).toBe(false);
        for (const it of r.result.report.items) expect(it.message).toMatch(/[ぁ-んァ-ン一-龥]/);
      });
    }
  }
});

describe('corpus: the premerged packages are well-formed', () => {
  it.each(manifest.filter((e) => e.order === 'shuf').map((e) => [e.file, e.base ?? 'base.xlsx']))('%s: every kept formula is a formula of the merged sheet, tokenizes cleanly and reads no source sheet', async (file, baseFile) => {
    const r = await runCorpusFile(DIR, file, { results: 'nocache', imports: 'all', join: 'full' }, baseFile);
    const book = await readBook(r.result.bytes, 'm.xlsx', { id: 'm' });
    const sheet = sheetOf(book, r.result.layout.sheet)!;
    let n = 0;
    for (const t of r.trace.filter((x) => x.outcome === 'kept')) {
      const c = sheet.rows[t.row - 1]?.[t.col - 1];
      expect(c?.f, `${file} ${t.source}`).toBeTruthy();
      expect(c!.f).toBe(t.formula);
      const toks = tokenize(c!.f!);
      expect(toks.some((x) => x.type === 'unknown'), t.formula).toBe(false);
      expect(c!.f).not.toMatch(/#REF!/);
      for (const tk of toks) if (tk.type === 'ref') expect(tk.prefix?.sheet ?? null, t.formula).toBeNull();
      n++;
    }
    expect(n).toBe(r.counts.kept);
    expect((await snapshot(r.result.bytes)).fullCalcOnLoad).toBe(true);
  });
});

describe('corpus: what the findings say', () => {
  it('a source without stored results keeps the formulas that can stay live (the user\'s complaint: they used to become empty cells)', async () => {
    const r = await runCorpusFile(DIR, 'f04_lookups__shuf.xlsx', { results: 'nocache', imports: 'default', join: 'left' });
    expect(r.counts.kept).toBe(r.counts.total);
    expect(r.counts.empty).toBe(0);
    const old = await runCorpusFile(DIR, 'f03_keycol__shuf.xlsx', { results: 'nocache', imports: 'default', join: 'left' });
    expect(old.counts.substituted).toBeGreaterThan(0); // =A2&"様" reads the base ID column
  });

  it('the Excel-saved twin and the result-less file give the same formulas', async () => {
    for (const e of manifest.filter((x) => x.order === 'shuf' && !/f02_|f10_|f16_/.test(x.file))) {
      const a = await runCorpusFile(DIR, e.file, { results: 'cached', imports: 'default', join: 'left' }, e.base ?? 'base.xlsx');
      const b = await runCorpusFile(DIR, e.file, { results: 'nocache', imports: 'default', join: 'left' }, e.base ?? 'base.xlsx');
      // (f02: the nocache twin has no formulas; f10: XlsxWriter's spills; f16: Excel turns the full-width + of one formula into a plain +)
      // kept / not kept is the same; a not-kept formula is a value (results stored) or empty (none stored)
      const key = (t: { srcRow: number; srcCol: number; outcome: string; formula?: string }) => `${t.srcRow}:${t.srcCol}:${t.outcome === 'kept' ? 'kept' : 'not kept'}:${t.formula ?? ''}`;
      expect(b.trace.map(key).sort(), e.file).toEqual(a.trace.map(key).sort());
      expect(summarize(a.trace).kept).toBe(summarize(b.trace).kept);
    }
  });

  it('an .xlsm source (macro-enabled) is imported like an .xlsx', async () => {
    const lib = await import('../oracle/import-values/lib');
    const pipeline = lib.buildPipeline(await lib.loadKeySource(path.join(DIR, 'base.xlsx'), 'b'), await lib.loadKeySource(path.join(DIR, 'cached', 'f01_samerow__same.xlsm'), 's1'), { imports: 'default', joinType: 'left' });
    expect(pipeline.src.book.format).toBe('xlsm');
    const { buildPremerged } = await import('../../src/core/xlsx/premerge');
    const res = await buildPremerged(lib.toPremergeInput(pipeline));
    const xlsx = await runCorpusFile(DIR, 'f01_samerow__same.xlsx', { results: 'cached', imports: 'default', join: 'left' });
    expect(res.report.formulasKept).toBe(xlsx.counts.kept);
    expect(res.report.formulasKept).toBe(216); // 8 formula columns x 27 matched people
  });
});
